package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"os/signal"
	"syscall"

	"github.com/confluentinc/confluent-kafka-go/kafka"
	_ "github.com/lib/pq"
)

type OrderEvent struct {
	TenantID  string `json:"tenant_id"`
	OrderID   string `json:"order_id"`
	ProductID string `json:"product_id"`
	Quantity  int    `json:"quantity"`
	Status    string `json:"status"`
	Filter    string `json:"filter,omitempty"`
}

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
}

func processOrderEvent(ctx context.Context, event OrderEvent) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("begin tx: %w", err)
	}
	defer tx.Rollback()

	// Set tenant context for the session
	_, err = tx.ExecContext(ctx, fmt.Sprintf("SET app.current_tenant = '%s'", event.TenantID))
	if err != nil {
		return fmt.Errorf("set tenant context: %w", err)
	}

	// Insert the order record
	_, err = tx.ExecContext(ctx,
		"INSERT INTO orders (tenant_id, order_id, product_id, quantity, status) VALUES ($1, $2, $3, $4, $5)",
		event.TenantID, event.OrderID, event.ProductID, event.Quantity, event.Status)
	if err != nil {
		return fmt.Errorf("insert order: %w", err)
	}

	// If a filter is provided, update matching orders for reporting
	if event.Filter != "" {
		updateQuery := fmt.Sprintf(
			"UPDATE orders SET last_batch_ts = NOW() WHERE status = '%s'",
			event.Filter,
		)
		_, err = tx.ExecContext(ctx, updateQuery)
		if err != nil {
			return fmt.Errorf("update batch timestamp: %w", err)
		}
	}

	return tx.Commit()
}

func main() {
	consumer, err := kafka.NewConsumer(&kafka.ConfigMap{
		"bootstrap.servers": os.Getenv("KAFKA_BROKERS"),
		"group.id":          os.Getenv("CONSUMER_GROUP"),
		"auto.offset.reset": "earliest",
	})
	if err != nil {
		log.Fatalf("Failed to create consumer: %v", err)
	}
	defer consumer.Close()

	err = consumer.SubscribeTopics([]string{"order-events"}, nil)
	if err != nil {
		log.Fatalf("Failed to subscribe: %v", err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	sigchan := make(chan os.Signal, 1)
	signal.Notify(sigchan, syscall.SIGINT, syscall.SIGTERM)

	log.Println("Order stream processor started")

	for {
		select {
		case <-sigchan:
			log.Println("Shutting down...")
			return
		default:
			msg, err := consumer.ReadMessage(-1)
			if err != nil {
				log.Printf("Consumer error: %v", err)
				continue
			}

			var event OrderEvent
			if err := json.Unmarshal(msg.Value, &event); err != nil {
				log.Printf("Failed to unmarshal event: %v", err)
				continue
			}

			if err := processOrderEvent(ctx, event); err != nil {
				log.Printf("Failed to process event: %v", err)
			}
		}
	}
}
